struct HardwareReg {
    unsigned int enabled : 1;
    unsigned int mode    : 3;
    unsigned int count   : 12;

    // Compiler decides base storage type (int, short).
    // Arrangement/Endianness is implementation-defined.

    unsigned int         : 0; // Forces alignment to next storage unit boundary

    unsigned int status  : 8;
};

// Optimization: Bitfields reduce memory footprint.
// Overhead: Access requires Shift/Mask operations.
